import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.HashSet; import java.util.Set; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String nStr = br.readLine(); if (nStr == null) return; int n = Integer.parseInt(nStr.trim()); String s = br.readLine(); if (s == null) return; boolean[] found = new boolean[26]; for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); if (c >= 'a' && c <= 'z') { found[c - 'a'] = true; } } boolean allVowels = found['a' - 'a'] && found['e' - 'a'] && found['i' - 'a'] && found['o' - 'a'] && found['u' - 'a']; if (allVowels) { System.out.println("YES"); } else { System.out.println("NO"); } } }